import { LandingShowcase } from './LandingShowcase';
import { LandingWork } from './LandingWork';

/* =========================================================================
   LandingBody: the middle of the page, and the second per-site seam.

   The page SHELL is shared and must stay shared, because it carries the static-rendering setup
   (setRequestLocale), the metadata, and the FAQ schema, and a bug in any of those should be
   fixed once, not nine times. But WHICH SECTIONS a landing runs is a product decision, not a
   shell decision, and the first version of this file learned that the hard way: `page.tsx` was
   a shared file that hardcoded Showcase + Work, so syncing it into aiTAXI would have deleted
   aiTAXI's three real sections (how a fleet adopts the platform, the five operational modules,
   and an honest pre-launch roadmap) and replaced them with two sections it has no copy for.

   So the shell renders <LandingBody /> and this file is per-site. Most landings never touch it:
   the default below is the Showcase-then-Work pair the six were designed around. aiTAXI
   overrides it with its own three.

   Deleting a pre-launch platform's roadmap to make it match a template is not consistency, it
   is vandalism with a style guide.
   ========================================================================= */

export function LandingBody() {
  return (
    <>
      <LandingShowcase />
      <LandingWork />
    </>
  );
}
